import math


def sieve_of_atkin(limit):
    """Find all prime numbers up to the given limit using the Sieve of Atkin."""
    if limit < 2:
        return []
    if limit < 3:
        return [2]
    if limit < 5:
        return [2, 3]

    # Initialize sieve
    sieve = [False] * (limit + 1)
    sieve[2] = sieve[3] = True

    # Main sieve loop
    sqrt_limit = int(math.isqrt(limit)) + 1
    for x in range(1, sqrt_limit):
        for y in range(1, sqrt_limit):
            # n = 4x² + y²
            n = 4 * x * x + y * y
            if n <= limit and (n % 12 == 1 or n % 12 == 5):
                sieve[n] = not sieve[n]

            # n = 3x² + y²
            n = 3 * x * x + y * y
            if n <= limit and n % 12 == 7:
                sieve[n] = not sieve[n]

            # n = 3x² - y² (only when x > y)
            if x > y:
                n = 3 * x * x - y * y
                if n <= limit and n % 12 == 11:
                    sieve[n] = not sieve[n]

    # Eliminate composites: multiples of squares of primes
    for i in range(5, sqrt_limit):
        if sieve[i]:
            step = i * i
            for j in range(step, limit + 1, step):
                sieve[j] = False

    return [i for i, is_prime in enumerate(sieve) if is_prime]


if __name__ == "__main__":
    limit = 100
    primes = sieve_of_atkin(limit)
    print(f"Primes up to {limit}: {primes}")
    print(f"Count: {len(primes)}")
